    "abstractSummaryId": "BACKGROUND: Social and emotional learning (SEL) is crucial for developing skills such as emotional regulation, cooperation, and goal achievement. Deficits in these skills are linked to later academic and behavioral problems. While SEL interventions have been widely implemented internationally, few have been tested in early childhood settings in Japan, and their effectiveness remains unclear. In 2022, the Fun FRIENDS social and emotional learning program was introduced in class units for 4-5-year-olds attending kindergartens and children's schools in Wakayama Prefecture, Japan. Thus, this study examined the eff...",
