    "title": "Is the Association Between Early Childhood Screen Media Use and Effortful Control Bidirectional? A Prospective Study During the COVID-19 Pandemic",
    "authors": "Fitzpatrick, C., et al.",
    "year": 2022,
    "journalName": "Frontiers in Psychology",
    "volumeIssue": "13, 918834–918834",
    "publisherOrAccreditation": "Frontiers Media · Open Access (Terverifikasi DOI)",
    "doi": "10.3389/fpsyg.2022.918834",
