    "license": "Open Access · CC-BY",
    "keywords": [
      "screen media use",
      "early childhood",
      "effortful control",
      "bidirectional relationship"
    ],
    "abstractSummaryId": "Individual differences in effortful control, a component of temperament, reflecting the ability to use attention and other cognitive processes to self-regulate emotion and behavior, contribute to child academic adjustment, social competence, and wellbeing. Research has linked excessive screen time in early childhood to reduced self-regulation ability. Furthermore, research suggests that parents are more likely to use screens with children who have more challenging temperaments, such as low levels of effortful control. Since screen time by children between the ages of 0 and 18 has increased during the COVID-19...",
    "methodology": "Studi Longitudinal",
    "sampleContext": "Tercatat dalam abstrak artikel: N= 316, (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "Child screen time at age 3.5 significantly contributed to decreased effortful control scores at the age of 4.5, whereas effortful control at age 3.5 did not contribute to screen time at age 4.5.",
      "Our results partially confirmed our hypothesis and indicated that higher levels of screen time intake were detrimental to the development of effortful control.",
      "These results suggest that screen media use, an exceedingly frequent activity, may play an enduring role in development by shaping young children’s temperaments."
    ],
    "implications": "Rujukan primer terbuka (Frontiers in Psychology, 2022); gunakan tautan DOI untuk verifikasi data lengkap, tabel statistik, dan teks penuh artikel.",
