    "keywords": [
      "early psychosis",
      "maternal psychosis",
      "family history of psychosis",
      "protective factors"
    ],
    "abstractSummaryId": "Background: Early identification of sub-clinical psychotic experiences in at-risk individuals is vital to prevent the development of psychosis, even before prodromal symptoms emerge. A widely-replicated risk factor is having a family member with psychosis. The Environmental Risk (E-Risk) Longitudinal Twin Study has shown that better cognitive functioning, a stimulating family environment, and a cohesive community, are protective against psychotic experiences among children; while engaging in physical activity, social support, and a cohesive community are protective for adolescents. In the current study we inve...",
    "methodology": "Studi Longitudinal",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "However, there were no significant interactions between these protective factors and maternal psychosis in relation to an absence of childhood or adolescent psychotic phenomena in the full sample, indicating that protective effects were not specific to this...",
      "Conclusions: These findings provide preliminary evidence that preventive interventions for early psychotic phenomena could focus on improving cognition, social support, and cohesiveness of the local community.",
      "Given scarce resources these might usefully be targeted at high-risk children."
    ],
