    "abstractSummaryId": "Introduction: Longitudinal studies of autistic children show that autism symptoms and emotional/behavioral problems vary and change over time. However, the factors that affect this variability remain far from certain and very little is known about what take place in the preschool period and the role of executive functions (EF). Methods: Here, we test the influence of stable difficulties in everyday executive functioning (EEF) during early childhood across 2 years on autistic symptoms and emotional and behavioral problems. Twenty-nine autistic children (24 males and 5 females) were assessed twice within the spa...",
