      "Discussion: Our results suggest that early and stable EEF plays the role of a modifier by interacting with the core domains of autism, in particular with the social affect domain (SA CSS), influencing social cognition and exacerbating or lessening symptom e...",
      "These short-term longitudinal and preliminary findings underscore the importance of EEF as necessary target for early intervention in children with autism."
