    "abstractSummaryId": "Inhibitory control (IC) is defined as the executive functioning (EF) and self-regulatory temperamental inhibition of impulsive or pre-potent behavior and has been consistently linked to multiple forms of childhood cognitive and socio-emotional maladjustment including academic and learning challenges, externalizing behaviors, and attention deficit hyperactivity disorder. However, the results of relevant investigations are somewhat dependent on the method of IC assessment and the theoretical approach of the researcher. The two primary theoretical perspectives on IC are the temperament and the EF approaches, and...",
