    "abstractSummaryId": "Purpose Evidence has shown neighborhood threat (NT) as a social driver of emotional and brain development. Few studies have examined the relationship between NT and neural function. Altered functional connectivity in the nucleus accumbens (NAcc) with the frontoparietal network (FPN) has been implicated in the development of substance use, however, little is known about perceived NT-related brain function or downstream alcohol sipping during early adolescence. This study examined the longitudinal relationship between youth and combined youth/parent perceived NT, resting state functional connectivity (RSFC) of t...",
