    "abstractSummaryId": "Executive functions (EF) are an important predictor of cognitive development. Early measures of EF are however rare. We extracted measurements of EF from the Bayley Scales of Infant and Toddler Development BSID-III, Bayley (2006) at age one, two and three years and investigated the effect of psychosocial stress, early-term birth and early childhood intervention on EF development. Families with psychosocial stress participated in a longitudinal RCT study implementing the home-visiting intervention program Parents-as-Teachers (PAT) (intervention group, N = 121 and control group, N = 111). Birth status (early-ter...",
