    "abstractSummaryId": "Autism spectrum disorder (ASD) is a complex neurodevelopmental condition that is commonly characterized by repetitive behaviors, limited interests, and difficulties in communication and social interaction (1). Motor system abnormalities, which are frequently overlooked or underestimated, are becoming increasingly recognized as potential biomarkers, even though basic socio-communicative features remain the standard diagnostic criteria (2). Among the numerous motor challenges that are commonly observed and have a cascading impact on cognitive and socio-emotional development are postural control, bilateral coordi...",
