    "abstractSummaryId": "The Hierarchical Taxonomy of Psychopathology (HiTOP) consortium recently defined the psychosis superspectrum (1) and focused on its nosology, etiology, and lifespan development (2). In the HiTOP bottom-up conceptual model, the psychosis superspectrum comprises two spectra -psychoticism and detachment -each consisting of traits and symptoms.Psychoticism includes four traits (fantasy proneness, unusual experiences, unusual beliefs, and peculiarity), two core symptom components (reality distortion and disorganization), and two additional symptom components (mania and dissociation), which are provisionally include...",
