    "methodology": "Survei Kuantitatif (Pemodelan Struktural / Regresi)",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The sense of gratitude served to increase these adolescents’ self-esteem, which previously decreased as a result of social comparison.",
      "This study had a number of weaknesses in the use of the instruments, especially the social comparison scale.",
      "Any similar study in the future is expected to focus more on one kind of social media."
    ],
