    "abstractSummaryId": "Health workers are professionals with high exposure to various types of stress; therefore, they need resilience to survive in their profession. This research aims to test the effect of social support and calling on resilience in health workers. It is a quantitative-correlational study conducted cross-sectionally. The instruments used were the Connor-Davidson Resilience Scale, Multidimensional Support Scale, and Calling Scale. Snowball sampling was used to identify participants, consisting of 113 health workers in East Nusa Tenggara province, Indonesia. The data were analyzed with multiple linear regression tec...",
