    "keyFindings": [
      "Amongst the types of social support, coworkers make the most significant contribution of 11.8% (p .01, F = 14.816), followed by family members at 9.6% (p .01, F = 11.752).",
      "On the other hand, social support from supervisors does not affect resilience (p .05, F = 0.904).",
      "Health workers should seek the social support they need proactively, and prospective health workers should consider their calling when choosing a career."
    ],
