      "Data dianalisis menggunakan teknik analisis Product Moment, hasil penelitian menunjukkan terdapat hubungan positif antara coping dan resiliensi yang nilai koefisien korelasinya sebesar 0,525 dengan p = 0,000 (p<0.01).",
