    "abstractSummaryId": "Quarter-life crisis is a psychosocial crisis in which individuals are vulnerable to experiencing psychological distress. One contributor to such distress is uncertainty intolerance, while personal growth initiative is a factor that can reduce it. This study examines Personal Growth Initiative (PGI) in determining the effect of uncertainty intolerance on psychological distress in individuals experiencing a quarter-life crisis. A total of 309 participants were selected through a screening process using the Quarter-life Crisis Questionnaire. The participants completed the Intolerance of Uncertainty Scale, General...",
