      "Moderation regression analysis was performed using the Hayes PROCESS Macro.",
      "The results indicate that personal growth initiative buffers the effect of uncertainty intolerance on psychological distress in individuals experiencing a quarter-life crisis (B = -0.193, p = .003, R2 = .117), but with differences shown based on age and gen...",
      "Based on the findings, it is necessary to build personal growth initiative skills, which will assist individuals in achieving and maximizing their potential and adapting well when faced with conditions of uncertainty."
