    "abstractSummaryId": "Teori Kontak merupakan salah satu teori Psikologi klasik yang paling banyak digunakan untuk membahas relasi antar kelompok. Beberapa ahli Psikologi Sosial mengemukakan bahwa teori ini menjadi pilihan utama dalam studi yang membahas relasi antar kelompok, terutama tentang conflik antar kelompok yang melibatkan prasangka. Meskipun demikian, bahasan tentang perkembangan Teori Kontak terutama dalam konteks Indonesia masih sangat terbatas. Penelitian ini bertujuan untuk memberi kontribusi terhadap pengetahuan baru melalui kajian literatur terkait dengan perkembangan Teori Kontak di Indonesia. Kajian literatur menun...",
