    "abstractSummaryId": "The growth of autistic self-advocacy and the neurodiversity movement has brought about new ethical, theoretical and ideological debates within autism theory, research and practice. These debates have had genuine impact within some areas of autism research but their influence is less evident within early intervention research. In this paper, we argue that all autism intervention stakeholders need to understand and actively engage with the views of autistic people and with neurodiversity as a concept and movement. In so doing, intervention researchers and practitioners are required to move away from a normative...",
