    "abstractSummaryId": "The relationship between product pricing and product packaging plays an important role in the buying behavior of consumers, whereas customer satisfaction plays a mediating role. To test these hypotheses, research was conducted on university students in China. Questionnaire-based convenience sampling was conducted on 500 students for data collection using online and offline sources. A total of 367 (73%) students responded, and 17 questionnaires were rejected due to missing information. SPSS and AMOS software were used for the data analysis. Product pricing and product information were independent variables in t...",
