    "abstractSummaryId": "Introduction While not all autism research is ableism, autism researchers can be ableist, including by talking about autistic people in sub-human terms (dehumanization), treating autistic people like objects (objectification), and making othering statements which set autistic people apart from non-autistic people, and below in status (stigmatization). Method This mixed-method study aimed to investigate how autism researchers construct autistic people and autism research, and to investigate whether including autistic people more in research relates to lower ableism in narratives about autistic people. We used a...",
