    "sampleContext": "Tercatat dalam abstrak artikel: N = 195 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "Instrumentality (a form of objectification) was key to whether researchers considered a person to have social value with emphasis revolving around intellectual ability and independence.",
      "Lastly, language seemed to act as a tool of normalization of violence.",
      "Researchers relied on an amorphous idea of “autism” when talking about prevention or eradication, potentially because it sounds more palatable than talking about preventing “autistic people,” despite autism only existing within the context of autistic people."
    ],
