    "abstractSummaryId": "Widespread and sustained engagement with health-protective behaviours (i.e., hygiene and distancing) is critical to successfully managing the COVID-19 pandemic. Evidence from previous emerging infectious disease outbreaks points to the role of perceived risk, worry, media coverage, and knowledge in shaping engagement with health-protective behaviours and vaccination intentions. The aim of the current study was to examine the role of these factors in predicting recommended health-protective behaviours early in the pandemic. A secondary aim was to assess uncertainty and misconceptions about COVID-19. An online s...",
