    "abstractSummaryId": "The Double Empathy Theory suggests that communicative difficulties between autistic and non-autistic people are due to bi-directional differences in communicative style and a reciprocal lack of understanding. If true, there should be increased similarity in interaction style, resulting in higher rapport during interactions between pairs of the same neurotype. Here, we provide two empirical tests of rapport, with data revealing whether self- and observer- rated rapport varies depending on the match or mismatch in autism status within a pair. An additional opportunity afforded by these data is to examine the eff...",
