    "abstractSummaryId": "IMPORTANCE: Vaccination hesitancy-the reluctance or refusal to be vaccinated-is a leading global health threat (World Health Organization, 2019). It is imperative to identify the prevalence of vaccination hesitancy for SARS-CoV2 in order to understand the scope of the problem and to identify its motivational roots in order to proactively prepare to address the problem when a vaccine eventually becomes available. OBJECTIVE: To identify (1) the prevalence of vaccination hesitancy for a SARS-CoV2 vaccine, (2) the motivational roots of this hesitancy, and (3) the most promising incentives for improving the likelih...",
