    "abstractSummaryId": "The Depression Anxiety Stress Scales (DASS; Lovibond and Lovibond, 1995b ) is a set of psychometrically sound scales that is widely used to assess negative emotional states in adults. In this project, we developed the Depression Anxiety Stress Scales for Youth (DASS-Y) and tested its psychometric properties. Data were collected from 2,121 Australian children and adolescents aged 7–18 (61% female). This sample was split randomly into a calibration group (n = 1075, 61% female) and a cross-validation group (n = 1046, 60% female). First, we used Confirmatory Factor Analysis on the calibration group to test the 3-f...",
