    "abstractSummaryId": "Objectives The study aims to investigate the state anxiety of parents of special needs children during the 2019 coronavirus disease (COVID-19) epidemic and the influence of parental stress, social support, and other related variables on the anxiety of parents. Methods Bespoke questionnaires of children’s and parent’s mental and behavioral problems during the epidemic were used in the study. We also used the State Anxiety Inventory (S-AI), the Parenting Stress Index—Short Form-15 (PSI-SF-15), the NEO Five-Factor Inventory (NEO-FFI), and the Multidimensional Scale of Perceived Social Support (MSPSS). The data us...",
