    "keyFindings": [
      "Regression trees were developed to identify individuals at greater risk for anxiety, depression, and post-traumatic stress.",
      "Somatization and less reliance on adaptive defense mechanisms were associated with greater distress.",
      "These findings highlight the importance of assessing individuals’ physical experiences of psychological distress and emotion regulation strategies to help mental health providers tailor assessments and treatment during a global health crisis."
    ],
