    "abstractSummaryId": "Adolescence is an important developmental period marked by a transition from primarily parental-controlled eating to self-directed and peer-influenced eating. During this period, adolescents gain autonomy over their individual food choices and eating behavior in general. While parent-feeding practices have been shown to influence eating behaviors in children, little is known about how these relationships track across adolescent development as autonomy expands. The purpose of this qualitative study was to identify factors that impact food decisions and eating autonomy among adolescents. Using the food choice pr...",
    "methodology": "Penelitian Kualitatif",
