      "The degree of control that teens reported differed by eating location, occasion, and social context.",
      "Finally, adolescents demonstrated various levels of engagement in behaviors related to their eating autonomy.",
      "Identifying the emergent themes related to adolescent autonomy was the first step toward the goal of developing a scale to evaluate adolescent eating autonomy."
