    "keywords": [
      "health anxiety",
      "psychological flexibility",
      "COVID-19 lockdown",
      "peritraumatic distress"
    ],
    "abstractSummaryId": "The COVID-19 emergency has severely affected the Italian population. During a pandemic, those with high health anxiety are at risk of adverse mental health outcomes, including peritraumatic distress and mood disturbance. No prior research has explored the role of psychological flexibility in protecting people at high risk of poorer mental health impacts due to health anxiety during a pandemic. Psychological flexibility is the cornerstone of psychological health and resiliency. It involves behaving consistently with one’s chosen values even in the presence of emotional and mental discomfort. This study examined...",
