    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "Findings suggest embracing (rather than avoiding) inner discomfort and observing associated unhelpful thoughts, while also engaging in values-based action, increase resilience during adversity.",
      "Evidenced-based large-scale online public health interventions that target psychological flexibility in those experiencing health anxiety in the context of a pandemic are urgently needed.",
      "Many empirically-based ACT interventions are suited for this purpose."
    ],
