    "abstractSummaryId": "Modern societies increasingly show more egalitarian attitudes related to sexism and gender equality. However, there is still an important gender gap in wages and professions as well as in expectations surrounding male and female characteristics. Developmental studies carried out from an ecological perspective confirm that these influences come from the closest environments (mainly family and school) but also from more distant systems such as media or cultural values. As children are socialized in these norms and values, they increasingly internalize those schemes and use them to judge others, to choose friends...",
