    "keyFindings": [
      "Importantly, the model exhibited strong measurement invariance across female and male groups.",
      "Furthermore, the PSS-10 had adequate convergent validity for stressful life events (number: r = 0.13, p < 0.001; impact: r = 0.23, p < 0.001) and could explain incremental variance in predicting anxiety (ΔR2 = 0.13, β = 0.38, p < 0.001) and depression (ΔR2 ...",
      "Conclusions: A two-factor model best fits the structure of PSS-10 among Chinese adolescents, with strong measurement invariance between gender groups, demonstrating its validity for assessing perceived stress among Chinese adolescents."
    ],
