    "abstractSummaryId": "This study emphasizes the importance of analyzing factors that contribute to student well-being, as a result of the multiplicity of factors that can affect their quality of life (QoL). The literature indicates that, among these factors, emotional intelligence and self-regulation play a central role in influencing adolescents' psychological and scholastic well-being. Technology is a fundamental aspect of adolescent life but addiction to the use of smartphones is increasing, which can affect both emotional intelligence and self-regulation, and in turn individual well-being and QoL. Therefore, this study explores...",
