    "abstractSummaryId": "The purpose of this multi-study article was to investigate the roles of adaptability and social support in predicting a variety of psychological outcomes. Data were collected from Year 12 college students (N= 73; Study 1), university students (N= 102; Study 2), and non-studying members of the general public (N= 141; Study 3). Findings showed that, beyond variance attributable to social support, adaptability made a significant independent contribution to psychological wellbeing (life satisfaction, psychological wellbeing, flourishing, and general affect) and psychological distress across all studies. Beyond the...",
