    "abstractSummaryId": "In contexts of exposure to atypical stress or adversity, individual and collective resilience refers to the process of sustaining wellbeing by leveraging biological, psychological, social and environmental protective and promotive factors and processes (PPFPs). This multisystemic understanding of resilience is generating significant interest but has been difficult to operationalize in psychological research where studies tend to address only one or two systems at a time, often with a primary focus on individual coping strategies. We show how multiple systems implicated in human resilience can be researched in...",
