    "abstractSummaryId": "The authenticity of heritage tourism is an important factor for attracting tourists. Research has shown that authenticity is related to revisit intention. However, little attention has been paid to the impact of heritage tourism authenticity on revisit intention. Drawing on cognitive appraisal theory, we constructed a model of the mechanism underlying this relationship. Questionnaires were distributed at one world heritage site (the Dujiangyan irrigation system) in China, and data from 596 valid cases were collected. Using structural equation modeling, the results showed that authenticity, directly and indirec...",
