    "abstractSummaryId": "Old-age loneliness is a global problem with many members of the scientific community suspecting increased loneliness in the elderly population during COVID-19 and the associated safety measures. Although hypothesized, a direct comparison of loneliness before and during the pandemic is hard to achieve without a survey of loneliness prior to the pandemic. This study provides a direct comparison of reported loneliness before and during the pandemic using 1:1 propensity score matching (PSM) on a pre- and a peri-pandemic sample of elderly (60+ years) individuals from Lower Austria, a county of Austria (Europe). Dif...",
