    "abstractSummaryId": "Therapeutic landscapes encapsulate healing and recovery notions in natural and built environmental settings. Tourists' perceptions determine their decision making of health and wellness tourism consumption. Researchers struggle with the conceptualization of the term 'therapeutic landscapes' across disciplines. Drawing on extant literature searched in nine databases, this scoping review identifies different dimensions of therapeutic landscapes. Out of identified 178 literature sources, 124 met the inclusion criteria of identified keywords. We review the contribution and the potential of environmental psychology...",
